from lib import *
S = SS('n5')
steps = [
    step("Group 的全部秘密在三个函数里:joinPaths 用 path.Join 拼 basePath 和相对路径,再看相对路径是否以 / 结尾,是就给结果补回斜杠;Group() 新建一个 RouterGroup,basePath 是拼好的绝对路径,Handlers 是 combineHandlers 复制出来的一份;combineHandlers 新分配一个切片,先拷贝 group.Handlers,再拷贝这条路由自己的 handler。", t=tl(S(1)), mark=lidx(S(1), 'path.Join(absolutePath, relativePath)', "lastChar(relativePath) == '/'"), done=lidx(S(1), 'mergedHandlers := make(HandlersChain, finalSize)', 'copy(mergedHandlers, group.Handlers)', 'basePath: group.calculateAbsolutePath(relativePath)'), kv=KV([['路径', 'path.Join,相对路径以 / 结尾就补回 /'], ['handler', '注册时新分配切片拷贝,不共享底层数组']], ['handler'])),
    step("11 种拼法:Group(\"/api\").GET(\"/users\") 与 Group(\"/api/\").GET(\"users\") 都得 /api/users;GET(\"/users/\") 保留结尾斜杠(/api/users/);GET(\"\") 得 /api,GET(\"/\") 得 /api/;Group(\"api\")(没有开头斜杠)也得 /api/users;Group(\"/\") 与 Group(\"\") 的 BasePath 都是 \"/\";Group(\"/api//v1\").GET(\"//users\") 被化简成 /api/v1/users;含 .. 的 Group(\"/api/v1/..\") 得 /api/users。", t=tl(S(2)), mark=lidx(S(2), 'GET("")', 'GET("/")', '//users', '/api/v1/..'), done=lidx(S(2), 'Group("/api").GET("/users")', 'Group("api")'), kv=KV([['/api + users', '/api/users'], ['结尾斜杠', '保留:/users/ → /api/users/'], ['//、..', 'path.Join 会化简']], ['结尾斜杠'])),
    step("嵌套 Group 的中间件依次叠加:/ping 只有全局一个中间件加 handler,共 2 个;/api/a 3 个;/api/v1/b 4 个;/api/v1/admin/c 在 global、api、v1、admin 之后还有路由自己的 c-only,加上 handler 共 6 个。执行顺序是外层到内层再原路返回(洋葱):global api v1 admin c-only [h] /c-only /admin /v1 /api /global。", t=tl(S(3)), mark=lidx(S(3), 'GET /api/v1/admin/c', 'handlers=6'), done=lidx(S(3), 'GET /ping', 'GET /api/a', 'GET /api/v1/b'), b=bars([['/ping', 2, '2 个'], ['/api/a', 3, '3 个'], ['/api/v1/b', 4, '4 个'], ['/api/v1/admin/c', 6, '6 个']], 6, done=[0, 1, 2], mark=[3]), kv=KV([['/api/v1/admin/c', '6 个:global, api, v1, admin, c-only, handler'], ['执行顺序', '进入时由外向内,返回时由内向外']], ['/api/v1/admin/c'])),
    step("handler 链在注册那一刻就拼好了:r.Use 之前注册的 /before 没有中间件;Use 之后的 /after 有 late;g.Use(g-late) 之后注册的 /g/own 有 late 和 g-late,但在 g.Use 之前就创建的子组 sub 下的 /g/s/x 只有 late,没有 g-late;g2 里 Use 之前注册的 /g2/early 也只有 late。", t=tl(S(4)), mark=lidx(S(4), '/before      → [h]', '/g/s/x', '/g2/early'), done=lidx(S(4), '/after', '/g/own', '/g2/late'), kv=KV([['/before', '没有中间件'], ['/g/s/x', '子组在 g.Use 之前创建,没有 g-late'], ['/g2/early', 'Use 之前注册,没有 g2-late']], ['/g/s/x'])),
    step("Engine.Use 会调用 rebuild404Handlers 和 rebuild405Handlers(gin.go 342–343 行),把全局中间件拼进 404/405 的 handler 链;Group.Use 不会。所以 /g/nothing 虽然在 /g 前缀下,404 时只经过全局的 A,没有经过 G;/nothing 也是只有 A。注册了的 /g/ok 则 A、G 都走。", t=tl(S(5)), mark=lidx(S(5), 'gin.go: 342', 'gin.go: 343', '/g/nothing'), done=lidx(S(5), '/g/ok'), kv=KV([['Engine.Use', '重建 404 / 405 的 handler 链'], ['Group.Use', '不碰 404 / 405']], ['Group.Use'])),
]
A = mkartn('n5', 5, 'Gin,路由分组,Group,中间件继承,basePath,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 Group:11 种路径拼法的结果(path.Join 化简斜杠和 ..,结尾斜杠保留);嵌套 Group 里一条路由最终的 handler 个数;handler 链在注册那一刻拼好,之后再 Use 不影响已注册的路由和已创建的子组;Group.Use 不会让 404 经过组中间件。',
    'Group 只是路径前缀加一份中间件的拷贝?这篇逐个验证:路径怎么拼、嵌套组的中间件怎么叠加、什么时候“固化”,以及一个容易忽略的结论——在组里 Use 的中间件管不到这个前缀下的 404。',
    [('6 个', '/api/v1/admin/c 这条路由最终的 handler 数'), ('0 次', '子组在 g.Use 之前创建时,它的路由里 g-late 执行的次数'), ('A,没有 G', '请求 /g/nothing(404)时经过的中间件')],
    [('路径怎么拼', '<p><code>joinPaths</code> 用标准库的 <code>path.Join</code> 拼起来,所以重复斜杠和 <code>..</code> 会被化简;只有一个例外:相对路径以 <code>/</code> 结尾时,结果会补回结尾斜杠。<code>GET("")</code> 注册的是组自己的路径,<code>GET("/")</code> 注册的是带结尾斜杠的路径,两者是不同的路由。</p>'),
     ('11 种拼法', '<p>开头斜杠、结尾斜杠、空串、<code>//</code>、<code>..</code> 的各种组合都落到了一个规整的绝对路径上。注意 <code>Group("/api/")</code> 的 <code>BasePath()</code> 保留了结尾斜杠(<code>"/api/"</code>),拼路由时才被 <code>path.Join</code> 化简。</p>'),
     ('嵌套与洋葱顺序', '<p>每一层 Group 把自己的 <code>Handlers</code> 复制一份再加上新的中间件,路由注册时再把路由自己的 handler 拼在最后。<code>DumpTree</code> 里能看到 /api/v1/admin/c 上有 6 个 handler。执行时 <code>c.Next()</code> 之前的代码从外向内,之后的代码从内向外。</p>'),
     ('Use 的时机', '<p>因为拼接发生在注册时(<code>combineHandlers</code> 复制出新切片),之后再调用 <code>Use</code> 影响不到已经注册的路由,也影响不到<b>在 Use 之前创建的子组</b>。典型的坑:先写路由、最后才补一个 <code>r.Use(auth)</code>,前面的路由全都没有鉴权。</p>'),
     ('404 与组中间件', '<p>全局 <code>Engine.Use</code> 会重建 404/405 的 handler 链,所以 404 页面也经过日志、恢复等全局中间件;<code>Group.Use</code> 只改组自己的 <code>Handlers</code>,所以 <code>/g/nothing</code> 这种“在组前缀下但没注册”的路径,404 时不会经过组里的中间件。</p>')],
    steps,
    [ENV_N_GIN + '。DumpTree 是源码副本里加的只读打印函数(用来数每条路由的 handler 个数);中间件和 handler 都用 fmt.Print 记录执行顺序;请求用 httptest 直接调用 ServeHTTP;每种情形各一次',
     '没有验证:Group.Use 对 NoRoute / NoMethod 自定义 handler 的影响(只验证了默认 404);大量嵌套(超过 63 个 handler 的上限 abortIndex)时的 panic 文案(源码里有断言,没有触发);并发地创建 Group(Gin 要求注册路由时单线程,没有测);Group 与 Static 系列函数组合时的路径拼接'],
    'Group 与 basePath')
